package typeinfo

// PreserveAdaptiveEncoding returns fresh with its storage encoding pinned to
// existing's encoding, when both TypeInfos represent the same type family that
// uses a variable adaptive encoding. This prevents a freshly-constructed
// TypeInfo from silently adopting the global adaptive-encoding default (see
// UseAdaptiveEncoding) when the column was originally persisted under a legacy
// address encoding, which would corrupt reads of data written by an older
// version of Dolt.
//
// It is a no-op (returns fresh unchanged) when existing is nil, when the two
// TypeInfos belong to different type families (e.g. VARCHAR->TEXT, or
// Point->LineString), or when the type family does not use variable adaptive
// encoding (e.g. integer types). It returns nil when fresh is nil.
//
// The SQL type semantics of fresh (e.g. a widened MaxCharacterLength) are
// preserved; only the storage encoding is carried over from existing.
func PreserveAdaptiveEncoding(existing TypeInfo, fresh TypeInfo) TypeInfo {
	if existing == nil || fresh == nil {
		return fresh
	}
	if !sameAdaptiveEncodingFamily(existing, fresh) {
		return fresh
	}
	return fresh.WithEncoding(existing.Encoding())
}

// sameAdaptiveEncodingFamily reports whether existing and fresh are the same
// concrete TypeInfo family that uses a variable adaptive encoding. Only these
// families have a meaningful choice between a legacy address encoding and the
// newer adaptive encoding, so only these need their encoding preserved.
func sameAdaptiveEncodingFamily(existing TypeInfo, fresh TypeInfo) bool {
	switch existing.(type) {
	case *blobStringType:
		_, ok := fresh.(*blobStringType)
		return ok
	case *varBinaryType:
		_, ok := fresh.(*varBinaryType)
		return ok
	case *jsonType:
		_, ok := fresh.(*jsonType)
		return ok
	case *pointType:
		_, ok := fresh.(*pointType)
		return ok
	case *linestringType:
		_, ok := fresh.(*linestringType)
		return ok
	case *polygonType:
		_, ok := fresh.(*polygonType)
		return ok
	case *multipointType:
		_, ok := fresh.(*multipointType)
		return ok
	case *multilinestringType:
		_, ok := fresh.(*multilinestringType)
		return ok
	case *multipolygonType:
		_, ok := fresh.(*multipolygonType)
		return ok
	case *geomcollType:
		_, ok := fresh.(*geomcollType)
		return ok
	case *geometryType:
		_, ok := fresh.(*geometryType)
		return ok
	default:
		return false
	}
}
